<div class="table-responsive"><table class="table"><thead><tr><th><?= \App\Support\I18n::html('Product') ?></th><th><?= \App\Support\I18n::html('Paid / free') ?></th><th><?= \App\Support\I18n::html('Unit LKR') ?></th><th><?= \App\Support\I18n::html('Discount LKR') ?></th><th><?= \App\Support\I18n::html('Total LKR') ?></th><th><?= \App\Support\I18n::html('Stock needed / available') ?></th></tr></thead><tbody><?php foreach($displayLines as $line): ?><tr><td data-label="<?= \App\Support\I18n::html('Product') ?>"><?= $e($line['sku'].' — '.\App\Support\I18n::product(['name'=>$line['product_name'],'name_si'=>$line['name_si']??null])) ?><?php if($line['rule_snapshot']): ?><small class="d-block"><?= $e($line['rule_snapshot']['name']) ?></small><?php endif; ?></td><td data-label="<?= \App\Support\I18n::html('Paid / free') ?>"><?= $e($line['paid_quantity'].' / '.$line['free_quantity']) ?></td><td data-label="<?= \App\Support\I18n::html('Unit LKR') ?>"><?= $e($line['unit_price']) ?></td><td data-label="<?= \App\Support\I18n::html('Discount LKR') ?>"><?= $e($line['discount_amount']) ?></td><td data-label="<?= \App\Support\I18n::html('Total LKR') ?>"><?= $e($line['payable_amount']) ?></td><td data-label="<?= \App\Support\I18n::html('Stock needed / available') ?>"><?= $e($line['required_stock'].' / '.$line['available_quantity']) ?></td></tr><?php endforeach; ?></tbody></table></div>
